const N=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];const scales={major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10]};export function analyzeHarmony(notes){if(!Array.isArray(notes))throw Error('Notes MIDI requises');const valid=notes.filter(n=>!n.muted&&Number.isInteger(n.midi)&&n.midi>=0&&n.midi<=127&&Number.isFinite(n.step));const histogram=Array(12).fill(0);for(const n of valid)histogram[n.midi%12]++;const total=valid.length;const keys=[];if(total)for(let root=0;root<12;root++)for(const [mode,intervals] of Object.entries(scales))keys.push({root:N[root],mode,coverage:intervals.reduce((s,i)=>s+histogram[(root+i)%12],0)/total});keys.sort((a,b)=>b.coverage-a.coverage);const groups=new Map();for(const n of valid){const s=groups.get(n.step)||new Set();s.add(n.midi%12);groups.set(n.step,s)}const chords=[];for(const [step,pitches] of groups){if(pitches.size<3)continue;for(let root=0;root<12;root++)for(const [quality,third] of [['major',4],['minor',3]])if([0,third,7].every(i=>pitches.has((root+i)%12)))chords.push({step,root:N[root],quality});}return {histogram,keyCandidates:keys.slice(0,6),chordCandidates:chords.sort((a,b)=>a.step-b.step),limitations:['Coverage heuristics; relative keys ambiguous; chord candidates use simultaneous note onsets only.']};}